import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_mult2gap_kernel(const float* __restrict__ input,
                                      float* __restrict__ output,
                                      float multiplier,
                                      int N, int C, int H, int W) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < N * C) {
        int n = index / C;
        int c = index % C;
        float sum_val = 0.0f;
        int offset = (n * C + c) * H * W;
        for (int hw = 0; hw < H * W; hw++) {
            sum_val += input[offset + hw];
        }
        // Multiply by 'multiplier' and then take the average.
        sum_val = (sum_val * multiplier) / static_cast<float>(H * W);
        // The second global average pooling over the same dimensions has no effect,
        // so we omit it. The final result shape remains [N, C, 1, 1].
        output[index] = sum_val;
    }
}

torch::Tensor fused_mult2gap(torch::Tensor x, float multiplier) {
    TORCH_CHECK(x.dim() == 4, "Input must be 4D.");
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto out = torch::zeros({N, C, 1, 1}, x.options());

    int total = N * C;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    fused_mult2gap_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        multiplier,
        N, C, H, W
    );

    return out;
}
"""

fused_source_cpp = r"""
torch::Tensor fused_mult2gap(torch::Tensor x, float multiplier);
"""

fused_module = load_inline(
    name="fused_mult2gap",
    cpp_sources=fused_source_cpp,
    cuda_sources=fused_source,
    functions=["fused_mult2gap"],
    verbose=False
)


class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, multiplier):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size,
                                                 stride=stride, padding=padding,
                                                 output_padding=output_padding)
        self.multiplier = multiplier

    def forward(self, x):
        x = self.conv_transpose(x)
        # Fused multiplier and global average pooling kernel
        x = fused_module.fused_mult2gap(x, self.multiplier)
        return x
